format_code:
chip esp32

channel data: int[16]

shared var total: int = 0

task producer {
    every 1s {
        total += 1
        data.send(total)
    }
}

task consumer {
    every 500ms {
        if data.has_data() {
            var val: int = data.receive()
            total -= val
        }
    }
}

system_graph.mermaid:
flowchart LR
    v_total("total")
    c_data[/"data"/]
    u_producer(("producer<br>↻ 1s"))
    u_consumer(("consumer<br>↻ 500ms"))
    u_producer -->|write| v_total
    u_producer -->|send| c_data
    v_total -.->|read| u_producer
    c_data -.->|has_data, receive| u_consumer
    u_consumer -->|write| v_total
